public class Main {
    public static boolean isPalindrome(int n) {
        int original = n;
        int reverse = 0;
        while (n > 0) {
            reverse = reverse * 10 + n % 10;
            n /= 10;
        }
        return original == reverse;
    }

    public static void main(String[] args) {
        System.out.println(isPalindrome(1221));
    }
}

